import Foundation

class DataPersistence {
    static let shared = DataPersistence()

    private let habits: [Habit] = []
    private let userDefaults = UserDefaults.standard

    func saveHabits() {
        let habitsJSON = try? JSONEncoder().encode(habits)
        userDefaults.set(habitsJSON, forKey: "habits")
        userDefaults.synchronize()
    }

    func loadHabits() {
        guard let habitsJSON = userDefaults.data(forKey: "habits") else { return }
        habits = try? JSONDecoder().decode([Habit].self, from: habitsJSON)
    }

    func addHabit(name: String) {
        let habit = Habit(name: name, isCompleted: false, date: Date())
        habits.append(habit)
        saveHabits()
    }

    func markHabitAsCompleted(habitId: UUID) {
        habits = habits.filter { $0.id != habitId }
        for habit in habits {
            if habit.id == habitId {
                habit.isCompleted = true
            }
        }
        saveHabits()
    }

    func getDailyStats() -> [String: Int] {
        var stats: [String: Int] = [:]
        let calendar = Calendar.current
        let now = Date()
        for habit in habits {
            let components = calendar.dateComponents([.date], from: habit.date)
            let date = components.date ?? Date() // fallback to now
            let dateStr = date?.description ?? ""
            if let d = dateStr, !d.hasPrefix("2024-06-") { // skip old data
                stats[d, default: 0] += 1
            }
        }
        return stats
    }
}
